            && !gem.subclassExhaustiveStrategy().hasValue()
            && !gem.unmappedTargetPolicy().hasValue()
            && !gem.unmappedSourcePolicy().hasValue()
            && !gem.ignoreByDefault().hasValue()
            && !gem.builder().hasValue() ) {

