   296	    private boolean isRedefined(Set<String> redefinedNames, String inheritedName ) {
   297	        if ( inheritedName != null ) {
   298	            for ( String redefinedName : redefinedNames ) {
   299	                if ( elementsAreContainedIn( inheritedName, redefinedName ) ) {
   300	                    return true;
   301	                }
   302	            }
   303	        }
   304	        return false;
   305	    }
   306	
   307	    private boolean elementsAreContainedIn( String redefinedName, String inheritedName ) {
   308	        if ( inheritedName != null && redefinedName.startsWith( inheritedName ) ) {
   309	            // it is possible to redefine an exact matching source name, because the same source can be mapped to
   310	            // multiple targets. It is not possible for target, but caught by the Set and equals method in
   311	            // MappingOptions. SourceName == null also could hint at redefinition
   312	            if ( redefinedName.length() > inheritedName.length() ) {
   313	                // redefined.lenght() > inherited.length(), first following character should be separator
   314	                return '.' == redefinedName.charAt( inheritedName.length() );
   315	            }
   316	        }
   317	        return false;
   318	    }
