   130	    private List<SourceMethod> retrievePrototypeMethods(TypeElement mapperTypeElement,
   131	            MapperOptions mapperAnnotation) {
   132	        if ( !mapperAnnotation.hasMapperConfig() ) {
   133	            return Collections.emptyList();
   134	        }
   135	
   136	        TypeElement typeElement = asTypeElement( mapperAnnotation.mapperConfigType() );
   137	        List<SourceMethod> methods = new ArrayList<>();
   138	        for ( ExecutableElement executable : elementUtils.getAllEnclosedExecutableElements( typeElement ) ) {
   139	
   140	            if ( executable.isDefault() || executable.getModifiers().contains( Modifier.STATIC ) ) {
   141	                // skip the default and static methods because these are not prototypes.
   142	                continue;
   143	            }
   144	
   145	            ExecutableType methodType = typeFactory.getMethodType( mapperAnnotation.mapperConfigType(), executable );
   146	            List<Parameter> parameters = typeFactory.getParameters( methodType, executable );
   147	            boolean containsTargetTypeParameter = SourceMethod.containsTargetTypeParameter( parameters );
   148	
   149	            // prototype methods don't have prototypes themselves
   150	            List<SourceMethod> prototypeMethods = Collections.emptyList();
   151	
   152	            SourceMethod method =
   153	                getMethodRequiringImplementation(
   154	                    methodType,
   155	                    executable,
   156	                    parameters,
   157	                    containsTargetTypeParameter,
   158	                    mapperAnnotation,
   159	                    prototypeMethods,
   160	                    mapperTypeElement
   161	                );
   162	
   163	            if ( method != null ) {
   164	                methods.add( method );
   165	            }
   166	        }
   167	
   168	        return methods;
   169	    }
