   171	    /**
   172	     * Retrieves the mapping methods declared by the given mapper type.
   173	     *
   174	     * @param usedMapperType The type of interest (either the mapper to implement, a used mapper via @uses annotation,
   175	     *                   or a parameter type annotated with @Context)
   176	     * @param mapperToImplement the top level type (mapper) that requires implementation
   177	     * @param mapperOptions the mapper config
   178	     * @param prototypeMethods prototype methods defined in mapper config type
   179	     * @return All mapping methods declared by the given type
   180	     */
   181	    private List<SourceMethod> retrieveMethods(Type usedMapperType, TypeElement mapperToImplement,
   182	                                               MapperOptions mapperOptions, List<SourceMethod> prototypeMethods) {
   183	        List<SourceMethod> methods = new ArrayList<>();
   184	
   185	        TypeElement usedMapper = usedMapperType.getTypeElement();
   186	        for ( ExecutableElement executable : elementUtils.getAllEnclosedExecutableElements( usedMapper ) ) {
   187	            SourceMethod method = getMethod(
   188	                usedMapperType,
   189	                executable,
   190	                mapperToImplement,
   191	                mapperOptions,
   192	                prototypeMethods );
   193	
   194	            if ( method != null ) {
   195	                methods.add( method );
   196	            }
   197	        }
   198	
   199	        //Add all methods of used mappers in order to reference them in the aggregated model
   200	        if ( usedMapper.equals( mapperToImplement ) ) {
   201	            for ( DeclaredType mapper : mapperOptions.uses() ) {
   202	                TypeElement usesMapperElement = asTypeElement( mapper );
   203	                if ( !mapperToImplement.equals( usesMapperElement ) ) {
   204	                    methods.addAll( retrieveMethods(
   205	                        typeFactory.getType( mapper ),
   206	                        mapperToImplement,
   207	                        mapperOptions,
   208	                        prototypeMethods ) );
   209	                }
   210	                else {
   211	                    messager.printMessage(
   212	                        mapperToImplement,
   213	                        mapperOptions.getAnnotationMirror(),
   214	                        Message.RETRIEVAL_MAPPER_USES_CYCLE,
   215	                        mapperToImplement
   216	                    );
   217	                }
   218	            }
   219	        }
   220	
   221	        return methods;
   222	    }
