   228	    private SourceMethod getMethod(Type usedMapperType,
   229	                                   ExecutableElement method,
   230	                                   TypeElement mapperToImplement,
   231	                                   MapperOptions mapperOptions,
   232	                                   List<SourceMethod> prototypeMethods) {
   233	        TypeElement usedMapper = usedMapperType.getTypeElement();
   234	        ExecutableType methodType = typeFactory.getMethodType( (DeclaredType) usedMapperType.getTypeMirror(), method );
   235	        List<Parameter> parameters = typeFactory.getParameters( methodType, method );
   236	        Type returnType = typeFactory.getReturnType( methodType );
   237	
   238	        boolean methodRequiresImplementation = method.getModifiers().contains( Modifier.ABSTRACT );
   239	        boolean containsTargetTypeParameter = SourceMethod.containsTargetTypeParameter( parameters );
   240	
   241	        //add method with property mappings if an implementation needs to be generated
   242	        if ( ( usedMapper.equals( mapperToImplement ) ) && methodRequiresImplementation ) {
   243	            return getMethodRequiringImplementation( methodType,
   244	                method,
   245	                parameters,
   246	                containsTargetTypeParameter,
   247	                mapperOptions,
   248	                prototypeMethods,
   249	                mapperToImplement );
   250	        }
   251	        // otherwise add reference to existing mapper method
   252	        else if ( isValidReferencedMethod( parameters ) || isValidFactoryMethod( method, parameters, returnType )
   253	            || isValidLifecycleCallbackMethod( method )
   254	            || isValidPresenceCheckMethod( method, parameters, returnType ) ) {
   255	            return getReferencedMethod( usedMapper, methodType, method, mapperToImplement, parameters );
   256	        }
   257	        else {
   258	            return null;
   259	        }
   260	    }
