   358	    private ParameterProvidedMethods retrieveContextProvidedMethods(
   359	            List<Parameter> contextParameters, TypeElement mapperToImplement, MapperOptions mapperConfig) {
   360	
   361	        ParameterProvidedMethods.Builder builder = ParameterProvidedMethods.builder();
   362	        for ( Parameter contextParam : contextParameters ) {
