   367	                contextParam.getType(),
   368	                mapperToImplement,
   369	                mapperConfig,
   370	                Collections.emptyList() );
   371	
   372	            List<SourceMethod> contextProvidedMethods = new ArrayList<>( contextParamMethods.size() );
   373	            for ( SourceMethod sourceMethod : contextParamMethods ) {
   374	                if ( sourceMethod.isLifecycleCallbackMethod() || sourceMethod.isObjectFactory()
