   470	        int validSourceParameters = 0;
   471	        int targetParameters = 0;
   472	        int targetTypeParameters = 0;
   473	
   474	        for ( Parameter param : parameters ) {
   475	            if ( param.isMappingTarget() ) {
   476	                targetParameters++;
   477	            }
   478	            else if ( param.isTargetType() ) {
   479	                targetTypeParameters++;
   480	            }
   481	            else if ( !param.isMappingContext() ) {
